#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

const int MOD = 1000000007;

int add(int a, int b) {
    a += b;
    if (a >= MOD) a -= MOD;
    return a;
}

int sub(int a, int b) {
    if (a >= b) return a - b;
    return a + MOD - b;
}

int mul(long long a, long long b) {
    return (a * b) % MOD;
}

int modPow(int base, int exp) {
    int result = 1;
    while (exp > 0) {
        if (exp & 1) result = mul(result, base);
        base = mul(base, base);
        exp >>= 1;
    }
    return result;
}

int n;
int prob[8][8];
int match[8][8];
int tripleMask[7][7][7];
int fullMask;
int dp[1048576];
int answer;

bool checkTriple(int x, int y, int z) {
    int vals[4] = {0, x, y, z};
    int idx[4] = {0, 1, 2, 3};
    do {
        bool ok = true;
        for (int i = 1; i <= 3; ++i) {
            if (!match[idx[i]][vals[i]]) {
                ok = false;
                break;
            }
        }
        if (ok) return true;
    } while (next_permutation(idx + 1, idx + 4));
    return false;
}

void forwardDFS(int cur, int r, int c) {
    if (!cur) return;
    if (r == 4) {
        bool used[7] = {false, true, true, true, true, true, true};
        int state = 0;
        for (int i = 1; i <= 6; ++i) {
            for (int j = i + 1; j <= 6; ++j) {
                for (int k = j + 1; k <= 6; ++k) {
                    if (checkTriple(i, j, k)) {
                        used[i] = used[j] = used[k] = false;
                        int a = -1, b = -1, c = -1;
                        for (int l = 1; l <= 6; ++l) {
                            if (!used[l]) {
                                if (a == -1) a = l;
                                else if (b == -1) b = l;
                                else c = l;
                            }
                        }
                        used[i] = used[j] = used[k] = true;
                        if (c != -1) state |= tripleMask[a][b][c];
                    }
                }
            }
        }
        dp[state] = add(dp[state], cur);
        return;
    }
    match[r][c] = 1;
    int nextVal = mul(cur, prob[r][c]);
    if (c == 6) forwardDFS(nextVal, r + 1, 1);
    else forwardDFS(nextVal, r, c + 1);
    match[r][c] = 0;
    nextVal = mul(cur, sub(1, prob[r][c]));
    if (c == 6) forwardDFS(nextVal, r + 1, 1);
    else forwardDFS(nextVal, r, c + 1);
}

void backwardDFS(int cur, int r, int c) {
    if (!cur) return;
    if (r == 7) {
        int state = 0;
        for (int i = 1; i <= 6; ++i) {
            for (int j = i + 1; j <= 6; ++j) {
                for (int k = j + 1; k <= 6; ++k) {
                    if (checkTriple(i, j, k)) state |= tripleMask[i][j][k];
                }
            }
        }
        answer = add(answer, mul(cur, dp[fullMask ^ state]));
        return;
    }
    match[r - 3][c] = 1;
    int nextVal = mul(cur, prob[r][c]);
    if (c == 6) backwardDFS(nextVal, r + 1, 1);
    else backwardDFS(nextVal, r, c + 1);
    match[r - 3][c] = 0;
    nextVal = mul(cur, sub(1, prob[r][c]));
    if (c == 6) backwardDFS(nextVal, r + 1, 1);
    else backwardDFS(nextVal, r, c + 1);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> n;
    int inv100 = modPow(100, MOD - 2);
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            int x; cin >> x;
            prob[i][j] = mul(x, inv100);
        }
    }
    for (int i = n + 1; i <= 6; ++i) prob[i][i] = 1;
    int cnt = 0;
    for (int i = 1; i <= 6; ++i) {
        for (int j = i + 1; j <= 6; ++j) {
            for (int k = j + 1; k <= 6; ++k) {
                tripleMask[i][j][k] = 1 << cnt;
                ++cnt;
            }
        }
    }
    fullMask = (1 << cnt) - 1;
    forwardDFS(1, 1, 1);
    int totalBits = (1 << cnt);
    for (int bit = 0; bit < cnt; ++bit) {
        for (int mask = 0; mask < totalBits; ++mask) {
            if (mask & (1 << bit)) {
                dp[mask] = add(dp[mask], dp[mask ^ (1 << bit)]);
            }
        }
    }
    answer = 0;
    backwardDFS(1, 4, 1);
    answer = sub(1, answer);
    cout << answer << '\n';
    return 0;
}
